function sol=polygon_qp_branch(fr,g,o,cfg,codes,z0,scale,prior)
clock=tic;model=cfg.mechanicalModel;[A,b,Aeq,beq,lb,ub,meta]=tsfs.polygon_qp_constraints(fr,g,model,codes,scale,cfg.trustRadius);nx=numel(z0);ny=meta.ny;J=[model.e.J zeros(numel(model.e.r),ny-nx)];r0=model.e.r-model.e.J*z0;H=1e-4*(J'*J);H=(H+H')/2;f=1e-4*J'*r0;
opts=optimoptions('quadprog','Algorithm','interior-point-convex','Display','off','MaxIterations',100,'OptimalityTolerance',1e-8,'ConstraintTolerance',cfg.constraintTolerance);
y0=[z0;zeros(ny-nx,1)];exception='';try,[y,~,exitflag,stats,multipliers]=quadprog(H,f,A,b,Aeq,beq,lb,ub,[],opts);catch err,y=[];exitflag=-99;stats=struct('iterations',0,'firstorderopt',NaN);multipliers=[];exception=[err.identifier ': ' err.message];end
if isempty(y),y=y0;end;e=tsfs.linearized_evaluate(fr,g,y(1:nx),scale,model);violation=max([abs(Aeq*y-beq);A*y-b;lb-y;y-ub;0]);modes=codes;modes(codes>=2)=2;stationarity=NaN;if isfield(stats,'firstorderopt'),stationarity=stats.firstorderopt;end
sol=struct('z',y(1:nx),'scale',scale,'prior',prior,'evaluation',e,'converged',exitflag>0,'reason',sprintf('quadprog-exit-%d',exitflag),'iterations',stats.iterations,'trace',[],'counts',struct('augmentedIVPs',0,'rhsEvaluations',0,'odeSegments',0,'failedIVPs',0,'affineEvaluations',1),'seconds',toc(clock),'stationarity',stationarity,'objectiveScale',1e-4,'historySource','fixed-previous-frame','solver','octagon-branch-QP','solverStats',stats,'exitflag',exitflag,'multipliers',multipliers,'initialZ',z0,'initialY',y0,'mode',modes,'modeY',[],'qpY',y,'qpMeta',meta,'modeViolation',violation,'modeFeasible',violation<=cfg.constraintTolerance,'exception',exception,'initialViolation',max([abs(Aeq*y0-beq);A*y0-b;lb-y0;y0-ub;0]));
end
